    onSelectCodeList: function(component, codeDvcd) {
        var me = this;
        var D = new Ext.Deferred();

        Ext.Ajax.request({
            headers: {
                viewId : me.getViewId(),
                serviceId : 'BomMtgSvc.findOneCodelist'
            },
            jsonData : {
                codeDvcd : codeDvcd,
                stcd : Constants.stcd.NORMAL,
            },
            scope : me,
            success : function(response) {

                var comboboxData = [];

                var res = Ext.JSON.decode(response.responseText);

                //         ComboboxUtils.makeCustomCbx(component, res.result);
                //         if(Ext.isEmpty(vm.get('content'))){
                //             // 비었으면 기본 장소
                //             component.setValue(mtgRoomDvcd);
                //         }
                //         else{
                //             // 안 비었으면 값에 대해 설정
                //             ComboboxUtils.setSelectFirstItem(component);

                //         }

                ComboboxUtils.makeCustomCbx(component, res.result);
                ComboboxUtils.setSelectFirstItem(component);

                D.resolve(res.result); // 성공

                this.onSelect();



            },
            failure : function(res, scope) {
                D.reject(); // 실패
            }

        });

        return D.promise;
    },

    onDatefieldChange: function(datefield, newDate, oldDate, eOpts) {
        this.getReferences().cal.getReferences().month.setValue(newDate);
        this.onSelect();
    },

    onComboboxChange: function(combobox, newValue, oldValue, eOpts) {
        var me = this;
        var refs = me.getReferences();

        if(!Ext.isEmpty(oldValue) && !Ext.isEmpty(newValue)){
            me.onSelect();
        }
    },

    onCheckboxChange: function(checkbox, newValue, oldValue, eOpts) {
        this.onSelect();
    },

    onMymonthValueChange: function(base, context, eOpts) {
        this.getReferences().dtpStDt.setValue(context.value);
    },

    /* 화면초기화 */
    initialize: function(component, eOpts) {
        var me = this;
        var refs = me.getReferences();
        var vm = me.getViewModel();

        // 회의실 콤보박스 설정
        me.onSelectCodeList(refs.selectedMtgRoomDvcd,'MTG');

        // 달력 클릭 이벤트 부여
        me.addEventListener();

        // 달력 조회
        // 날짜 선택 <-> 캘린더 -> 월 동기화
        var date =new Date();
        var mm = date.getMonth() +1;
        if(mm < 10){
            mm =  "0"+ mm;
        } else {
            mm = mm.toString();
        }
        refs.dtpStDt.setValue(date.getFullYear()+'년 ' + mm +"월");



        // 달력 사이드바 제거
        var calRefs = refs.cal.getReferences();
        calRefs.titleBar.setVisibility(false);
        if(!Ext.isEmpty(calRefs.sideBar)){
            calRefs.sideBar.setVisibility(false);
        }
    }

